import fs from 'fs';
import path from 'path';
export const dynamic='force-dynamic';
// data/seed.json is generated by seed.py and is NOT committed (personal contact data).
export async function GET(){
  try{ return Response.json(JSON.parse(fs.readFileSync(path.join(process.cwd(),'data','seed.json'),'utf8'))); }
  catch{ return Response.json({contacts:[],deals:[],events:[],queue:[],stats:{},error:'seed.json missing: run python3 seed.py'}); }
}
